              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "title": "Reply To"
          },
          "budget": {
            "default": 0,
            "title": "Budget",
            "type": "integer"
          }
        },
        "required": [
          "to",
          "body"
        ]
      }
    }
  ],
